pub fn prove_for_proof_accounts(
    public: Public<'_>,
    compiled: &PoolV1PairForestMergedC1CompilationV1,
    hash: HashFn,
    nonce_store: &mut DurableStateOnlyMaskNonceStore,
    mut proof_account: impl FnMut(usize) -> [u8; 32],
) -> Result<RetriedProof, Error> {
    prover::prove_masked_retrying_with(public, compiled, Variant::S2, hash, nonce_store, |k| {
        StateOnlyAttemptSecrets::generate_for_mask_nonce(proof_account(k)).map_err(|_| Error::Entropy)
    })
}

fn retry_attempt(
    public:Public<'_>,
    compiled:&PoolV1PairForestMergedC1CompilationV1,
    variant:Variant,
    hash:HashFn,
    nonce_store:&mut DurableStateOnlyMaskNonceStore,
    mut next_attempt:impl FnMut(usize)->Result<StateOnlyAttemptSecrets,Error>,
    k:usize,
)->Result<RetriedProof,Error> {
    if k>=ATTEMPT_CAP { return Err(Error::AttemptsExhausted); }
    let attempt=next_attempt(k)?;
    match prove_masked_attempt(public,compiled,variant,hash,attempt,nonce_store) {
        Ok((proof,audit))=>Ok(RetriedProof{proof,audit,attempts:k+1}),
        Err(Error::Rejected)=>retry_attempt(public,compiled,variant,hash,nonce_store,next_attempt,k+1),
        Err(e)=>Err(e),
    }
}

pub fn prove_masked_retrying_with(
    public:Public<'_>,
    compiled:&PoolV1PairForestMergedC1CompilationV1,
    variant:Variant,
    hash:HashFn,
    nonce_store:&mut DurableStateOnlyMaskNonceStore,
    next_attempt:impl FnMut(usize)->Result<StateOnlyAttemptSecrets,Error>,
)->Result<RetriedProof,Error> {
    if variant!=Variant::S2 { return Err(Error::Semantic); }
    retry_attempt(public,compiled,variant,hash,nonce_store,next_attempt,0)
}

pub fn generate_for_mask_nonce(
        mask_nonce: [u8; 32],
    ) -> Result<Self, StateOnlyAttemptEntropyError> {
        let limit=ENTROPY_RETRY_LIMIT;

        if !entropy_nonzero32(&mask_nonce) {
            return Err(StateOnlyAttemptEntropyError::RepeatedZeroBlock);
        }
        let mut retry=0;
        while retry<limit {
            let mut bytes = Zeroizing::new([0u8; 64]);
            getrandom::fill(bytes.as_mut())?;

            let mut field_mask_entropy = Zeroizing::new([0u8; 32]);
            let mut leaf_salt_seed = Zeroizing::new([0u8; 32]);
            field_mask_entropy.copy_from_slice(&bytes[..32]);
            leaf_salt_seed.copy_from_slice(&bytes[32..]);
            if entropy_nonzero32(&field_mask_entropy) && entropy_nonzero32(&leaf_salt_seed) {
                return Ok(Self {
                    mask_nonce,
                    field_mask_entropy,
                    leaf_salt_seed,
                });
            }
            retry+=1;
        }
        Err(StateOnlyAttemptEntropyError::RepeatedZeroBlock)
    }

